// REQ-011 — Claude "Conectores" (web/escritorio) solo pide URL + nombre: no
// puede mandar headers arbitrarios, así que la key también se acepta por query
// string como FALLBACK. El header x-api-key mantiene prioridad.
// NOTA: '?key=' NO es parte del estándar MCP — la spec define OAuth 2.1
// (opcional) como único mecanismo. Esto es un workaround pragmático, no la
// solución definitiva; si el cliente real descarta el query string entre
// llamadas, el plan B es key por ruta (/mcp/<key> vía redirect) o OAuth.
function getApiKey(event) {
  const headers = event.headers || {};
  if (headers["x-api-key"]) return headers["x-api-key"];
  const qs = event.queryStringParameters || {};
  return qs["x-api-key"] || qs.key || qs.api_key || qs.token || "";
}

// ── Social publishing (MCP ↔ api parity) ──
// The workspace api runs in this SAME Netlify site (netlify.toml: /api/* →
// api.mjs), so the social tools below forward the caller's OWN credentials
// to the very endpoints the human's publish dialog uses: the Express
// middleware then re-validates role and workspace, and there is exactly one
// publish pipeline (validation, provider calls, row locking) — never a
// second, drifting MCP-side copy of it.
const SOCIAL_PUBLISH_PROVIDERS = new Set(["buffer", "zernio"]);

function apiBaseUrl() {
  return (process.env.URL || "https://design.futuraria.com").replace(/\/$/, "");
}

/** Caller credentials in the exact shapes the api middleware accepts (auth.ts). */
function forwardApiHeaders(auth) {
  const headers = { "Content-Type": "application/json" };
  if (auth?.authType === "user" && auth.accessToken) headers["Authorization"] = `Bearer ${auth.accessToken}`;
  else if (auth?.authType === "workspace_key" && auth.keyRaw) headers["x-api-key"] = auth.keyRaw;
  else if (auth?.authType === "admin" && process.env.MCP_ADMIN_KEY) headers["x-api-key"] = process.env.MCP_ADMIN_KEY;
  return headers;
}

/** Call a workspace api route and unwrap its { success, data, error } envelope. */
/** Parse a JSON object out of an LLM reply that may wrap it in prose or code
 *  fences. Returns null when no object is present, so callers degrade
 *  gracefully instead of throwing on model chattiness. */
function parseLlmJson(text) {
  if (!text) return null;
  const fenced = text.match(/```(?:json)?\s*([\s\S]*?)```/);
  const candidate = fenced ? fenced[1] : text;
  const start = candidate.indexOf("{");
  const end = candidate.lastIndexOf("}");
  if (start < 0 || end <= start) return null;
  try { return JSON.parse(candidate.slice(start, end + 1)); } catch { return null; }
}

/** Native stacks a vision model writes when it is GUESSING instead of
 *  identifying. They stay legitimate candidates (a design may really use
 *  Arial) — import_design just names them back so the choice is conscious. */
const MCP_SYSTEM_FONT_STACKS = new Set([
  "arial", "helvetica", "sans-serif", "serif", "monospace", "system-ui",
  "-apple-system", "segoe ui", "times", "times new roman", "georgia",
  "verdana", "tahoma", "trebuchet ms", "courier", "courier new", "impact",
  "calibri", "cambria", "consolas", "cursive", "fantasy",
]);

// ── Provider-agnostic vision (Tier 2 fallback) ──
// Caller-side vision is the default and the right default: the chatting AI
// already holds the image in its own context. This helper exists for the rare
// harness that hands us pixels it never saw (text-only agents). Gemini is just
// ONE option here, never a requirement — openai → anthropic → google, stored
// BYOK first, then server env.
const VISION_PROVIDERS = ["openai", "anthropic", "google"];
const VISION_ENV_KEYS = { openai: "OPENAI_API_KEY", anthropic: "ANTHROPIC_API_KEY", google: "GEMINI_API_KEY" };

async function resolveVisionProvider(auth, explicit) {
  const order = explicit && explicit !== "caller" && explicit !== "auto" ? [explicit] : VISION_PROVIDERS;
  for (const provider of order) {
    if (auth?.userId) {
      try { const { key } = await getUserKey(auth.userId, provider); if (key) return { provider, key }; } catch { /* not stored */ }
    }
    const envKey = process.env[VISION_ENV_KEYS[provider]];
    if (envKey) return { provider, key: envKey };
  }
  return null;
}

/** Which vision providers the account could activate right now (for honest
 *  "you already have a key" advisories — never generic advice). */
async function listStoredVisionProviders(auth) {
  const stored = [];
  if (!auth?.userId) return stored;
  for (const provider of VISION_PROVIDERS) {
    try { const { key } = await getUserKey(auth.userId, provider); if (key) stored.push(provider); } catch { /* not stored */ }
  }
  return stored;
}

/** Fetch a remote design image for pixel analysis. Self-contained on
 *  purpose: match_color/match_font depend on it and must not lean on any
 *  in-flight helper from another workstream. */
async function fetchImageBytes(url) {
  const res = await fetch(String(url), { redirect: "follow" });
  if (!res.ok) throw { code: -32000, message: `Could not fetch image (HTTP ${res.status}): ${url}` };
  const type = (res.headers.get("content-type") || "image/png").split(";")[0].trim();
  if (!type.startsWith("image/")) throw { code: -32000, message: `URL does not point to an image (got ${type}): ${url}` };
  const buffer = Buffer.from(await res.arrayBuffer());
  if (buffer.length > 25 * 1024 * 1024) throw { code: -32000, message: "Image too large for pixel analysis (max 25MB)" };
  return { buffer, mimeType: type };
}

async function callVision({ provider, key, base64, mimeType, prompt, model }) {
  if (provider === "openai") {
    const res = await fetch("https://api.openai.com/v1/chat/completions", {
      method: "POST",
      headers: { "Content-Type": "application/json", Authorization: `Bearer ${key}` },
      body: JSON.stringify({
        model: model || "gpt-4o-mini",
        messages: [{ role: "user", content: [{ type: "text", text: prompt }, { type: "image_url", image_url: { url: `data:${mimeType};base64,${base64}` } }] }],
        max_tokens: 900,
        temperature: 0.1,
      }),
    });
    if (!res.ok) throw { code: -32000, message: `OpenAI vision error ${res.status}: ${(await res.text().catch(() => "")).substring(0, 200)}` };
    const j = await res.json();
    return j?.choices?.[0]?.message?.content || "";
  }
  if (provider === "anthropic") {
    const res = await fetch("https://api.anthropic.com/v1/messages", {
      method: "POST",
      headers: { "Content-Type": "application/json", "x-api-key": key, "anthropic-version": "2023-06-01" },
      body: JSON.stringify({
        model: model || "claude-3-5-haiku-latest",
        max_tokens: 900,
        temperature: 0.1,
        messages: [{ role: "user", content: [{ type: "image", source: { type: "base64", media_type: mimeType || "image/png", data: base64 } }, { type: "text", text: prompt }] }],
      }),
    });
    if (!res.ok) throw { code: -32000, message: `Anthropic vision error ${res.status}: ${(await res.text().catch(() => "")).substring(0, 200)}` };
    const j = await res.json();
    return (Array.isArray(j?.content) ? j.content.find(c => c.type === "text")?.text : null) || "";
  }
  // google (default)
  const res = await fetch(`https://generativelanguage.googleapis.com/v1beta/models/${model || "gemini-3.7-flash"}:generateContent?key=${key}`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({
      contents: [{ parts: [{ inlineData: { mimeType: mimeType || "image/png", data: base64 } }, { text: prompt }] }],
      generationConfig: { temperature: 0.1 },
    }),
  });
  if (!res.ok) throw { code: -32000, message: `Gemini vision error ${res.status}: ${(await res.text().catch(() => "")).substring(0, 200)}` };
  const j = await res.json();
  return j?.candidates?.[0]?.content?.parts?.[0]?.text || "";
}

const REGION_PROPOSER_PROMPT = `You are a design analyst. Identify the 2-6 most color-relevant REGIONS of this design (background, hero, title, button, accent, illustration...). Return ONLY JSON: {"regions":[{"role":"short role name","x":0.1,"y":0.05,"w":0.8,"h":0.15}]} — x/y/w/h are normalized 0..1 boxes, top-left origin. NEVER name colors; the server extracts them pixel-exactly from your boxes.`;

async function callWorkspaceApi(auth, path, { method = "GET", body } = {}) {
  const res = await fetch(`${apiBaseUrl()}${path}`, {
    method,
    headers: forwardApiHeaders(auth),
    ...(body !== undefined ? { body: JSON.stringify(body) } : {}),
  });
  const json = await res.json().catch(() => null);
  if (!res.ok || !json || json.success === false) {
    throw { code: -32000, message: (json && json.error) || `workspace api ${method} ${path} failed (HTTP ${res.status})` };
  }
  return json;
}

function getUserId(event) {
  const headers = event.headers || {};
  const apiKey = getApiKey(event);
  const bearer = (headers["authorization"] || "").replace("Bearer ", "");

  // If Supabase is configured and token looks like a JWT, try to verify it
  if (bearer && bearer.startsWith("eyJ") && bearer.split(".").length === 3) {
    const sb = getSupabase();
    if (sb) {
      try {
        // Store for async resolution later
        event._supabaseToken = bearer;
        // Return the raw JWT sub as fallback; actual verification happens in handler
        const payload = JSON.parse(Buffer.from(bearer.split(".")[1], "base64url").toString("utf8"));
        const userId = payload.sub || payload.user_id || payload.id;
        if (userId) return userId;
      } catch (_) {
        // JWT decode failed, fall through
      }
    }
  }

  // No JWT — validate API key (F5)
  if (apiKey) {
    // In development without Supabase, accept any key as user ID (backward compat)
    const sb = getSupabase();
    if (!sb) return apiKey;
    // Key sent as x-api-key — validate synchronously (fire-and-forget pattern,
    // but for correctness we accept the key and defer full validation to handler)
    // We hash the key and check the table; if it matches, return the userId
    return apiKey;
  }

  return apiKey || bearer || "dev_user_default";
}

// ── API Keys (F5) ──

/**
 * Hash a raw API key prefix for database storage.
 * Only the first 8 chars are stored as lookup; full key is never stored raw.
 */
function keyHash(rawKey) {
  // SHA-256 hex — keys are stored hashed, never in plain text
  return createHash("sha256").update(rawKey).digest("hex");
}

/**
 * Validate an API key against the database.
 * Returns { valid, userId, keyId, label, reason } or { valid: false, reason }.
 * `reason` is always populated on failure so callers and agents can self-diagnose
 * instead of guessing why authentication failed.
 */
async function validateApiKey(apiKey) {
  const sb = getSupabaseAdmin();
  if (!sb) {
    // No Supabase — accept any non-empty key as valid (dev mode)
    return apiKey ? { valid: true, userId: apiKey, keyId: "local", label: "Local Dev Key" } : { valid: false, reason: "no_api_key_provided" };
  }
  try {
    // Step 1: look up the key hash WITHOUT filtering on revoked_at / expires_at
    // so we can tell the caller exactly what's wrong.
    const { data: rawRow, error: lookupError } = await sb.from("workspace_api_keys")
      .select("id, created_by, workspace_id, role, label, revoked_at, expires_at, created_at, last_used_at")
      .eq("key_hash", keyHash(apiKey))
      .maybeSingle();
    if (lookupError) return { valid: false, reason: `database_error: ${lookupError.message}` };
    if (!rawRow) return { valid: false, reason: "key_not_found_in_database" };
    if (rawRow.revoked_at) return { valid: false, reason: `key_revoked_at_${rawRow.revoked_at}`, label: rawRow.label, keyId: rawRow.id };
    if (rawRow.expires_at && new Date(rawRow.expires_at) <= new Date()) {
      return { valid: false, reason: `key_expired_at_${rawRow.expires_at}`, label: rawRow.label, keyId: rawRow.id };
    }
    // Key is valid — update last_used_at fire-and-forget
    void sb.from("workspace_api_keys").update({ last_used_at: new Date().toISOString() }).eq("id", rawRow.id);
    return {
      valid: true,
      userId: rawRow.created_by,
      workspaceId: rawRow.workspace_id,
      role: rawRow.role,
      keyId: rawRow.id,
      label: rawRow.label,
      createdAt: rawRow.created_at,
      lastUsedAt: rawRow.last_used_at,
      expiresAt: rawRow.expires_at,
    };
  } catch (err) {
    return { valid: false, reason: `exception: ${err?.message || err}` };
  }
}

// ── Usage metering + monthly quota (migration v27) ──────────────────────
// Every authenticated tools/call that carries a workspaceId counts against
// that workspace's monthly total (workspace_usage, atomic via RPC). The
// quota lives in platform_config 'limits'.monthly_mcp_quota (0 = unlimited)
// and is enforced BEFORE the tool runs. Everything here fails OPEN: a
// missing table (pre-v27 migration) or a Supabase hiccup must never take
// the API down — worst case we stop counting, we never block legit work.
const __quotaCache = { value: null, fetchedAt: 0 };

async function getMonthlyQuota(sb) {
  if (__quotaCache.value !== null && Date.now() - __quotaCache.fetchedAt < 300_000) return __quotaCache.value;
  let quota = 5000;
  try {
    const { data } = await sb.from("platform_config").select("value").eq("key", "limits").maybeSingle();
    if (data?.value && typeof data.value.monthly_mcp_quota === "number") quota = data.value.monthly_mcp_quota;
  } catch { /* default */ }
  __quotaCache.value = quota;
  __quotaCache.fetchedAt = Date.now();
  return quota;
}

// Returns a JSON-RPC error RESPONSE when the workspace is over quota,
// or null when the call may proceed.
async function meterWorkspaceUsage(scopedParams, id, headers) {
  try {
    const wsId = scopedParams?.workspaceId;
    if (!UUID_RE.test(wsId || "")) return null;
    const sb = getSupabaseAdmin();
    if (!sb) return null;
    const quota = await getMonthlyQuota(sb);
    if (quota <= 0) return null;
    const month = new Date().toISOString().slice(0, 7);
    const { data: count, error } = await sb.rpc("increment_workspace_usage", { p_workspace_id: wsId, p_month: month, p_calls: 1 });
    if (error) return null; // pre-v27 or RPC missing → fail open
    if (Number(count) > quota) {
      return {
        statusCode: 200, headers,
        body: JSON.stringify(jsonRpcError(id, -32000,
          `Monthly MCP quota exceeded for this workspace (${Math.max(0, Number(count) - 1)}/${quota} calls used in ${month}). ` +
          "El contador se reinicia el día 1 del mes. Pedí al administrador ampliar el límite (Configuración → Plataforma).")),
      };
    }
    return null;
  } catch { return null; }
}

