            method: "POST",
            headers: {
              "Authorization": `Bearer ${rwKey}`,
              "Content-Type": "application/json",
              "X-Runway-Version": "2024-11-06",
            },
            body: JSON.stringify({ filename: `futuraria.${ext}`, type: "ephemeral" }),
            signal: abort.signal,
